# ListWeave: original synthetic list-maintenance module. CC0-1.0.
def blocks(values, width):
    if not isinstance(values, list) or type(width) is not int:
        raise TypeError("expected a list and integer width")
    if width <= 0:
        raise ValueError("width must be positive")
    complete_end = len(values) - len(values) % width
    return [values[start:start + width] for start in range(0, complete_end, width)]

